//! Ack — ported verbatim from the old-library scene data.

use super::super::tables::*;

pub(super) const AREAS: &[Area] = &[
    ("area:ack-angers-place", "Anger's Place", "This is Anger's Place, a district in the city of Ack. To the north is the Brass Ward. To the south is Piketown. To the west is the Copper Ward.", "region:ack", "culture:ackian"),
    ("area:ack-astar-ward", "Astar Ward", "This is the Astar Ward, a district in the city of Ack. To the northwest is Reinhold Wood. To the east is Gasper. To the south is the Brass Ward. To the south is the Red Ward. To the northwest is the road to Arathel County.", "region:ack", "culture:ackian"),
    ("area:ack-bank-hill", "Bank Hill", "This is Bank Hill, one of the more prosperous districts of the city of Ack. To the east is the Tin Ward. To the west is the Brass Ward.", "region:ack", "culture:ackian"),
    ("area:ack-carper-falls", "Carper Falls", "This is Carper Falls, a district in the city of Ack. To the north is the Copper Ward. To the east is Piketown. To the south is Poplar Gate. To the west is Sugar Heights.", "region:ack", "culture:ackian"),
    ("area:ack-copper-ward", "Copper Ward", "This is the Copper Ward, a district of the city of Ack. To the east is the Brass Ward. To the southeast is Carper Falls. To the west is the Squash Ward. To the southwest is Sugar Heights. To the northwest is the Dock Ward.", "region:ack", "culture:ackian"),
    ("area:ack-brass-ward-caliper-street-114", "Broken Baubles, 114 Caliper Street", "This is Broken Baubels, a store in the Brass Ward of the human metropolis of Ack. A rather unpopular shop, Broken Baubels sells relics of the prosperous and wonderous times before magic Broke. Glass displays are cluttered with broken lumorbs, non-functional pocket dragons, and other trinkets from the Magic Revolution. In the back corner is an autohearth, cast iron pipes rising out of it and penetrating the ceiling.", "region:brass-ward", "culture:ackian"),
    ("area:ack-brass-ward-caliper-street-street", "Caliper Street, Brass Ward, Ack", "This is Caliper Street, a bit northeast of where it intersects with the Kingsroad.", "region:brass-ward", "culture:ackian"),
    ("area:ack-brass-ward-kingsroad", "Kingsroad, Brass Ward", "This is the Kingsroad as it cuts east-west through the Brass Ward, one of the districts of Ack. To the east is Bank Hill. To the west is the Copper Ward. To the south is Anger's Place.", "region:brass-ward", "culture:ackian"),
    ("area:ack-dock-ward-harbour", "Ack Harbour", "This is the harbour of Ack, located at the mouth of the Green Delta where it spills into the Optic Ocean.", "region:dock-ward", "culture:ackian"),
    ("area:ack-dock-ward-main", "Dock Ward", "This is the Dock Ward, the oldest district in the city of Ack. Originally settled by humans retiring from a life fishing the Optic Ocean, the district is a hub of import and export. The blocks are filled with warehouses, and the streets are nearly blocked by the workers tent camps. Around the district is an unusual wooden wall. It was constructed by rolling decommissioned ships on their side, helping to protect against the militant tribes that then roamed the Central Plains.\n\nA bridge from here lead north across the murky brown Green River toward the North Ward. The Kingsroad cuts east and west through the district, leading to the Copper Ward and the harbour, respectively. Heading south through the maze of tents and warehouses leads to the Squash Ward.", "region:dock-ward", "culture:ackian"),
    ("area:ack-eastgate", "Eastgate", "This is Eastgate, the appropriately-named eastern gate of the city of Ack. The road here leads west into the Tin Ward, and east toward the town of Bellybrush.", "region:ack", "culture:ackian"),
    ("area:ack-garys-gate", "Gary's Gate", "This is Gary's Gate, which leads from Sugar Heights to the Widdershins Road.", "region:ack", "culture:ackian"),
    ("area:ack-gasper", "Gasper", "This is Gasper, a district in the city of Ack. To the southwest is the Astar Ward.", "region:ack", "culture:ackian"),
    ("area:ack-north-ward", "North Ward", "This is the North Ward, where Ack's first gentry moved to get away from the working class. To the north is the road to Arathel County. To the northeast is the Astar Ward. To the east is the Red Ward. To the south is the Dock Ward. To the northwest is the Wineglass.", "region:ack", "culture:ackian"),
    ("area:ack-piketown-gate", "Piketown Gate", "This is the Piketown Gate, leading from the Piketown district of Ack to the Widdershins Road. To the northwest is Piketown. To the south is Widdershins Road.", "region:ack", "culture:ackian"),
    ("area:ack-piketown", "Piketown", "This is Piketown, a district in the city of Ack. To the north is Anger's Place. To the southeast is the Piketown Gate. To the west is Carper Falls.", "region:ack", "culture:ackian"),
    ("area:ack-poplar-gate", "Poplar Gate", "This is Poplar Gate, leading from the Carper Falls district of Ack to the Widdershins Road. To the north is Carper Falls. To the south is the Widdershins Road.", "region:ack", "culture:ackian"),
    ("area:ack-red-ward", "Red Ward", "This is the Red Ward, one of Ack's oldest districts. Originally a keep constructed by one of Ack's first kings, the district's buildings are almost all constructed from the indigenous red clay. These days, the district is home to the eponymous Red Union, a conglomerate that has its hand in almost every contemporary human endeavor.", "region:ack", "culture:ackian"),
    ("area:ack-reinhard-wood", "Reinhard Wood", "This is Reinhold Wood, a district in the city of Ack. To the southeast is the Astar Ward.", "region:ack", "culture:ackian"),
    ("area:ack-squash-ward", "Squash Ward", "This is the Squash Ward, a district in the city of Ack. To the north is the North Ward.", "region:ack", "culture:ackian"),
    ("area:ack-sugar-heights", "Sugar Heights", "This is Sugar Heights, a district in the city of Ack. To the north is the Copper Ward. To the east is Carper Falls. To the southwest is Gary's Gate.", "region:ack", "culture:ackian"),
    ("area:ack-the-dog", "The Dog", "This is the Dog, a district in the city of Ack. To the southeast is Wineglass.", "region:ack", "culture:ackian"),
    ("area:ack-tin-ward", "Tin Ward", "This is the Tin Ward, a district of the city of Ack. To the east is the Eastgate. To the west is Bank Hill.", "region:ack", "culture:ackian"),
    ("area:ack-wineglass", "Wineglass", "This is Wineglass, a district in the city of Ack. To the southeast is the North Ward. To the northwest is the Dog.", "region:ack", "culture:ackian"),
];

