pub(super) const TRIVIA: &[Trivia] = &[
    ("area:ack-astar-ward", "The Astar Ward is named after the defunct Astar Empire, which once ruled current-day Ack, Arathel County, and Pled County."),
    ("area:ack-astar-ward", "The Astar Ward is the traditional home of many trade colleges."),
    ("area:ack-brass-ward-caliper-street-114", "During the Magic Revolution, 114 Caliper Street was the home and laboratory of Altar Sendvogue."),
    ("area:ack-red-ward", "Construction of the Red Ward began in 721bB."),
    ("area:ack-reinhard-wood", "Reinhard Wood, the residential district of Ack, is named for a forest that existed where the town of Arathel now is."),
    ("area:ack-squash-ward", "During the Fire of Ack, on the 14th of Blooming, 80aB, the Squash Ward was entirely destroyed. Since then, the Red Union has been rebuilding it as a visitor destination."),
];

pub(super) const LOOKABLES: &[Lookable] = &[
    ("lookable:ack-dock-ward-main-ack", "area:ack-dock-ward-main", "Ack", "This is the city of Ack, or at least, that of it visible from the Dock Ward. From here, you get the impression that the city is heavily-populated and busy with trade and industry."),
    ("lookable:ack-dock-ward-main-blocks", "area:ack-dock-ward-main", "blocks", "The city blocks here are not very block-y in shape. The streets instead yield to the footprint of the large warehouses, and are narrowed to paths by permanent tent encampments built throughout the Ward."),
    ("lookable:ack-dock-ward-main-bridge", "area:ack-dock-ward-main", "bridge", "A bridge to the north, made of iron, crosses the Green River and leads to the North Ward."),
    ("lookable:ack-dock-ward-main-clerks", "area:ack-dock-ward-main", "clerks", "There are a few bureaucrats from the Red Union walking around the Ward, doing inspections on various shops and warehouses."),
    ("lookable:ack-dock-ward-main-copper-ward", "area:ack-dock-ward-main", "Copper Ward", "The Copper Ward is the district east of here."),
    ("lookable:ack-dock-ward-main-graffiti", "area:ack-dock-ward-main", "graffiti", "The wall around the Dock Ward, separating it from the rest of the city, is covered in graffiti."),
    ("lookable:ack-dock-ward-main-harbour", "area:ack-dock-ward-main", "harbour", "To the west is the harbour, where ships berth."),
    ("lookable:ack-dock-ward-main-humans", "area:ack-dock-ward-main", "humans", "There are a lot of humans here in the Dock Ward, of various sorts. Many have darker complexions, revealing their time spent sailing the Optic Ocean. Others are dressed in red robes and have notably light complexions: the clerks of the Red Union, who rarely leave the towers of the Red Ward except on their bureaucratic assignments. One commonality is that most appear to be working class."),
    ("lookable:ack-dock-ward-main-kingsroad", "area:ack-dock-ward-main", "Kingsroad", "The Kingsroad is the widest boulevard in the district, going directly from the harbour, to the west, along the Green River to the city's Eastgate and out into the Green Delta beyond."),
    ("lookable:ack-dock-ward-main-north-ward", "area:ack-dock-ward-main", "North Ward", "The North Ward is well, north, across the Green River from here."),
    ("lookable:ack-dock-ward-main-optic-ocean", "area:ack-dock-ward-main", "Optic Ocean", "The Optic Ocean isn't visible from here, but the tang of churning algae is heavy in the air."),
    ("lookable:ack-dock-ward-main-green-river", "area:ack-dock-ward-main", "Green River", "This is near the mouth of the Green River. Here, the river's waters are a murky brown, and creep by, carrying the sewage of nearly every settlement between here and the Worldkeeper Mountains, a few thousand miles east."),
    ("lookable:ack-dock-ward-main-sailors", "area:ack-dock-ward-main", "sailors", "There are quite a few sailors here. This is the Dock Ward, after all: the harbour is just west of here."),
    ("lookable:ack-dock-ward-main-sewage", "area:ack-dock-ward-main", "sewage", "You don't need to have sewage described."),
    ("lookable:ack-dock-ward-main-ships", "area:ack-dock-ward-main", "ships", "The ships that make up the wall around the Dock Ward are old and covered in graffiti. Many of the ships show signs of severe fire damage."),
    ("lookable:ack-dock-ward-main-stores", "area:ack-dock-ward-main", "stores", "Some of the ships that make up the Dock Ward's outer wall have small stores tucked inside them."),
    ("lookable:ack-dock-ward-main-squash-ward", "area:ack-dock-ward-main", "Squash Ward", "The Squash Ward is the district south of here."),
    ("lookable:ack-dock-ward-main-tents", "area:ack-dock-ward-main", "tents", "The streets are filled with canvas tents: where the workers and various warehouses live."),
    ("lookable:ack-dock-ward-main-warehouses", "area:ack-dock-ward-main", "warehouses", "The Dock Ward is mostly warehouses these days, housing the goods coming in and out of the harbour. Most of the warehouses look recently constructed."),
    ("lookable:ack-dock-ward-main-wall", "area:ack-dock-ward-main", "wall", "The wall around the Dock Ward is made from old ships, too damaged to repair, that were dragged on shore and laid on their sides. Many of the ships have stores tucked inside them."),
    ("lookable:ack-red-ward-towers", "area:ack-red-ward", "towers", "Many of the buildings in the Red Ward are four or even six-storeys tall, but even they look small compared to the half dozen towers in the district, which each rise at least a dozen storeys."),
    ("lookable:ack-red-ward-buildings", "area:ack-red-ward", "buildings", "The buildings here form a maze of alleys, which once served as a great defense against invaders. These days, it simply serves to confuse tourists and inhibit trade. There are a few towers which rise higher than any other building."),
];

pub(super) const NOISES: &[Noise] = &[
    ("noise:ack-dock-ward-harbour-0", "area:ack-dock-ward-harbour", "1", "A young Union clerk monitoring those disembarking from the ships turns to his superior and asks, \"What do we do with a drunken sailor?\""),
    ("noise:ack-dock-ward-harbour-sailor-0", "npc:ack-dock-ward-harbour-sailor", "1", "The sailor picks at some lint on their uniform."),
    ("noise:ack-dock-ward-main-0", "area:ack-dock-ward-main", "2", "At the harbour, a sailor argues with a representative from the Red Union."),
    ("noise:ack-dock-ward-main-1", "area:ack-dock-ward-main", "1", "A young woman pulls a roll of paper from her satchel, tacks it to a segment of the Ward's wall, and paints over it with a paintbrush quickly, before pulling down the paper. Whatever message she meant to leave is entirely illegible. At least she tried."),
    ("noise:ack-red-ward-0", "area:ack-red-ward", "2", "A group of pedestrians wearing the uniform robes of the Red Union hurry down one street and up another, from one red tower to another."),
];

